"""Batched proposal-state conversion for the GPU oracle.

``_proposal_states`` in the evaluator is value-faithful but constructs one
nuPlan ``InterpolatedTrajectory`` per proposal (64 Python object builds per
window) before its single batched interpolation.  The knot structure those
objects encode is tiny and fixed -- current ego state followed by the eight
absolute proposal poses with zero velocity/acceleration/steering -- so this
module builds the knot arrays directly and interpolates with the same linear
rule.  Equivalence to the evaluator's function is pinned by test on real ego
objects.
"""

from __future__ import annotations

import numpy as np

from t4_e2e_devkit.planning.simulation.planner.pdm_planner.utils.pdm_enums import StateIndex


def proposal_states_fast(
    proposals: np.ndarray,  # [P, 8, 3] model-frame poses at 0.5 s
    ego,  # nuPlan EgoState (current)
    model_interval_s: float,
    proposal_num_poses: int,
    proposal_interval_s: float,
) -> np.ndarray:  # [P, proposal_num_poses + 1, 11]
    # The evaluator wraps each proposal in ``Trajectory``, whose contract is
    # float32; the poses re-enter float64 afterwards.  Replicate the rounding.
    proposals = np.asarray(proposals, dtype=np.float32).astype(np.float64)
    count, model_poses, _ = proposals.shape

    # Absolute transform of the model poses by the current rear axle.
    origin = ego.rear_axle
    cos_h, sin_h = np.cos(origin.heading), np.sin(origin.heading)
    absolute = np.empty_like(proposals)
    absolute[..., 0] = (
        origin.x + proposals[..., 0] * cos_h - proposals[..., 1] * sin_h
    )
    absolute[..., 1] = (
        origin.y + proposals[..., 0] * sin_h + proposals[..., 1] * cos_h
    )
    absolute[..., 2] = proposals[..., 2] + origin.heading

    # Knot arrays: [knots, field, P] with the current state prepended.  Future
    # knots carry zero velocity/acceleration/steering, exactly like
    # ``transform_trajectory``'s ``_se2_vel_acc_to_ego_state`` with [0, 0].
    split = ego.to_split_state()
    ego_linear = np.asarray(split.linear_states, dtype=np.float64)  # [8]
    ego_heading = float(split.angular_states[0])

    knots = model_poses + 1
    linear = np.zeros((knots, ego_linear.shape[0], count), dtype=np.float64)
    linear[0] = ego_linear[:, None]
    linear[1:, 1] = absolute[..., 0].T
    linear[1:, 2] = absolute[..., 1].T
    angular = np.zeros((knots, count), dtype=np.float64)
    angular[0] = ego_heading
    angular[1:] = absolute[..., 2].T

    # Query times, clipped into the knot range like the evaluator does.
    ego_time_s = ego.time_point.time_s
    times_s = np.arange(
        0.0,
        proposal_num_poses * proposal_interval_s + proposal_interval_s,
        proposal_interval_s,
    )
    query_us = np.clip(
        np.array([int((t + ego_time_s) * 1e6) for t in times_s], dtype=np.float64),
        ego.time_point.time_us,
        ego.time_point.time_us + int(model_poses * model_interval_s * 1e6),
    )
    knot_times = ego.time_point.time_us + np.arange(knots, dtype=np.float64) * (
        model_interval_s * 1e6
    )

    upper = np.clip(np.searchsorted(knot_times, query_us, side="left"), 1, knots - 1)
    lower = upper - 1
    fraction = (query_us - knot_times[lower]) / (knot_times[upper] - knot_times[lower])

    sampled_linear = (
        linear[lower] * (1.0 - fraction)[:, None, None]
        + linear[upper] * fraction[:, None, None]
    )  # [T, field, P]
    unwrapped = np.unwrap(angular, axis=0)
    sampled_angular = (
        unwrapped[lower] * (1.0 - fraction)[:, None]
        + unwrapped[upper] * fraction[:, None]
    )
    # nuPlan's principal_value (modulo form), matching the evaluator exactly.
    sampled_angular = ((sampled_angular + np.pi) % (2.0 * np.pi)) - np.pi

    states = np.zeros((count, len(times_s), StateIndex.size()), dtype=np.float64)
    states[..., StateIndex.X] = sampled_linear[:, 1, :].T
    states[..., StateIndex.Y] = sampled_linear[:, 2, :].T
    states[..., StateIndex.HEADING] = sampled_angular.T
    states[..., StateIndex.VELOCITY_X] = sampled_linear[:, 3, :].T
    states[..., StateIndex.VELOCITY_Y] = sampled_linear[:, 4, :].T
    states[..., StateIndex.ACCELERATION_X] = sampled_linear[:, 5, :].T
    states[..., StateIndex.ACCELERATION_Y] = sampled_linear[:, 6, :].T
    states[..., StateIndex.STEERING_ANGLE] = sampled_linear[:, 7, :].T
    return states
